5. Optional: Category-Specific Searches
For better results, you can target specific Amazon categories:
typescriptconst AMAZON_CATEGORIES = {
  'sneakers': '2983395011',      // Athletic Shoes
  'dress': '2983378011',         // Dresses
  'jacket': '2983367011',        // Coats & Jackets
  't-shirt': '1975277011',       // Shirts & Tees
  'jeans': '2983373011',         // Jeans
};

export function createAmazonAffiliateUrl(product: ProductIdentification): string {
  const searchQuery = buildSearchQuery(product);
  const categoryId = AMAZON_CATEGORIES[product.type.toLowerCase()];

  const params = new URLSearchParams({
    k: searchQuery,
    tag: AMAZON_ASSOCIATE_TAG,
  });

  // Add category refinement if we have it
  if (categoryId) {
    params.set('rh', `n:${categoryId}`);
  }

  return `${AMAZON_CA_BASE}/s?${params.toString()}`;
}
