```

### 4. Search Query Strategy for Awin
Since your Awin feed has specific formats, generate queries optimized for it:

```typescript
// Current Awin product names look like:
// "Adidas Taekwondo Mei W Sftm Black Sneakers"
// "NIKE Womens Grey Hoodie Dress Cotton Sleeveless"

// So searchQuery should match this pattern:
// "{Brand} {Gender indicator} {Color} {Product Type} {Material/Style}"
```

### 5. Post-Processing Improvements
Add a verification step that compares AI detection with Awin results:

```typescript
// Score Awin products against AI-detected attributes
function scoreAwinMatch(awinProduct: AwinProduct, detected: DetectedProduct): number {
  let score = 0;

  // Brand match in description
  if (detected.brand && awinProduct.description.toLowerCase().includes(detected.brand.toLowerCase())) {
    score += 10;
  }

  // Color match
  if (detected.visualAttributes.primaryColors.some(c => 
    awinProduct.product_name.toLowerCase().includes(c) ||
    awinProduct.description.toLowerCase().includes(c)
  )) {
    score += 5;
  }

  // Category/type match
  if (awinProduct.category_name.toLowerCase().includes(detected.subCategory)) {
    score += 5;
  }

  // Gender match
  if (detected.gender && awinProduct.product_name.toLowerCase().includes(detected.gender)) {
    score += 3;
  }

  return score;
}
